-- 0118_seed_bd_unions.sql
-- Seeds the union tier (0003's 4th location level, left untouched by 0116
-- since that source stopped at upazila) from the MIT-licensed
-- https://github.com/nuhil/bangladesh-geocode dataset — the only readily
-- available source with a full, self-consistent division/district/upazila/
-- union chain.
--
-- That dataset uses an older/alternate English transliteration for some
-- places than the one 0116 seeded from (e.g. "Comilla" vs the already-seeded
-- "Cumilla", "Chapainawabganj" vs "Nawabganj"). 8 of its 64 districts and 2 of
-- its 8 divisions hit this — hand-verified below as the same real place, not
-- guessed — and are aliased onto the existing rows so this doesn't duplicate
-- them. Below that level, upazila-name spelling drift is far more common (a
-- fifth of its ~494 upazilas don't match any seeded name at all, e.g. its
-- "Matlab North" for the already-seeded "Matlab Uttar") and reviewing each one
-- by hand wasn't worth it for this tier, so where no confident name match
-- exists, this seeds that upazila fresh too, under nuhil's own name, so its
-- unions have a home. That means a handful of upazila-level entries here may
-- read as near-duplicates of an existing upazila under a different spelling —
-- same fixable pattern as 0117's "dhaka"/"Dhaka" merge, left for manual
-- cleanup if any are spotted, rather than guessed at automatically here.
--
-- Idempotent — every insert is guarded by `where not exists` on type+name+
-- parent, so it's safe to run against a database that already has some of
-- this (including the "Staging ..." placeholder chain), or to re-run.

