join public.locations dd on dd.type = 'district' and dd.name = v.district_name
join public.locations uu on uu.type = 'upazila' and uu.name = v.upazila_name and uu.parent_id = dd.id
where not exists (
  select 1 from public.locations l where l.type = 'union' and l.name = v.name and l.parent_id = uu.id
);
